import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';

// --- DashboardMenuButton (Still contained within the banner's flexbox) ---
const DashboardMenuButton = ({ onMenuClick, isEasyMode, t }) => ( 
    <button
        onClick={onMenuClick}
        style={{ 
            // Pushes the button to the far right within the Flex container
            marginLeft: 'auto', 
            padding: '0', 
            backgroundColor: 'transparent', 
            border: 'none', 
            cursor: 'pointer',
            // Adjusted margin to pull it left
            marginRight: '20px', 
            fontSize: isEasyMode ? '36px' : '28px', 
            color: '#856404', 
            transition: 'color 0.2s',
            zIndex: 110, 
        }}
        onMouseOver={e => e.currentTarget.style.color = '#333'} 
        onMouseOut={e => e.currentTarget.style.color = '#856404'}
    >
        <span role="img" aria-label={t('general.menu')}>☰</span>
    </button>
);
// --- END DashboardMenuButton ---


// --- Icon Component Modification (Omitted for brevity) ---
const Icon = ({ name, emoji, isActive, onClick, isProminent, isEasyMode, keyName, color = '#1A73E8', bgColor = '#E8F0FE' }) => {
    // ... logic remains the same ...
    const isColored = isActive || isProminent; 
    let iconColor = color;
    let iconBgColor = '#E8F0FE'; 
    
    if (keyName === "dashboard.emergency_info_card") {
        iconColor = '#DC3545';
        iconBgColor = '#FDE9E9';
    } else if (keyName === "medical_menu.access_card_short") {
        iconColor = '#1A73E8';
        iconBgColor = '#E8F0FE';
    } else if (keyName === "dashboard.medical_history_card") {
        iconColor = '#17A2B8';
        iconBgColor = '#E8F7F9';
    }
    
    const baseFontSize = isEasyMode ? 32 : 18;
    let labelFontSize = baseFontSize;

    if (name && name.length > 12) {
        labelFontSize = isEasyMode ? 24 : 16;
    }


    return (
        <div 
            onClick={onClick} 
            style={{
                padding: '25px', 
                margin: '15px',
                border: `5px solid ${isColored ? iconColor : '#e0e0e0'}`,
                borderRadius: '15px', 
                width: '40%',
                textAlign: 'center',
                backgroundColor: isColored ? iconBgColor : '#ffffff',
                filter: isColored ? 'none' : 'grayscale(80%)',
                opacity: isColored ? 1 : 0.7, 
                cursor: 'pointer',
                boxShadow: isColored ? `0 8px 15px ${iconColor}4D` : '0 2px 5px rgba(0, 0, 0, 0.1)',
                transition: 'all 0.3s',
                fontSize: `${labelFontSize}px`, 
            }}
        >
            <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
            <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
        </div>
    );
};
// --- END Icon Component Modification ---


function Dashboard({ isEasyMode, goToMedical, onMenuClick, goToEmergencyInfo }) { 
    const { t } = useTranslation();

    const showAppointmentNotification = true; 
    
    // REFINED STYLING for the single, full-width banner
    const notificationStyle = {
        padding: '10px 15px', 
        // ***** ADJUSTMENT HERE *****
        marginTop: '45px', // Pushes the banner down from the top edge
        // ***************************
        margin: '0 15px 25px 15px', // Removes top margin, uses only new marginTop
        backgroundColor: '#FFF3CD', 
        color: '#856404', 
        cursor: 'pointer',
        fontWeight: 'bold',
        borderRadius: '10px', 
        border: '2px solid #FFC107', 
        boxShadow: '0 8px 15px rgba(255, 193, 7, 0.3)',
        zIndex: 10, 
        
        display: 'flex', 
        alignItems: 'center',
        
        width: 'auto', 
        boxSizing: 'border-box',
        
        animation: 'blink-alert 1.8s infinite alternate', 
    };

    // Styles for the text container
    const textContainerStyle = {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'flex-start',
        marginLeft: '15px', 
        flexGrow: 1, 
    }

    const bellStyle = {
        fontSize: isEasyMode ? '30px' : '22px', 
        color: '#FFC107',
        textShadow: '0 0 5px rgba(255, 193, 7, 0.8)',
    }

    const headingStyle = {
        fontSize: isEasyMode ? '24px' : '16px',
        margin: '0',
        lineHeight: '1.2',
        fontWeight: 'bold',
    }
    
    const tapHereStyle = {
        fontSize: isEasyMode ? '32px' : '22px',
        margin: '0',
        lineHeight: '1.2',
        fontWeight: '900',
    }


    return (
        <div style={{ position: 'relative' }}>
            
            {/* 1. THE UNIFIED, CLICKABLE BANNER (Now starting lower due to marginTop) */}
            {showAppointmentNotification && (
                <div onClick={goToMedical} style={notificationStyle}>
                    
                    {/* BELL ICON */}
                    <span role="img" aria-label={t('general.alert')} style={bellStyle}>🔔</span>
                    
                    {/* TEXT CONTAINER */}
                    <div style={textContainerStyle}>
                        <p style={headingStyle}>
                            {t('dashboard.appointment_soon_alert')}
                        </p>
                        <p style={tapHereStyle}>
                            {t('general.tap_here')}
                        </p>
                    </div>
                    
                    {/* MENU BUTTON (Relies on zIndex: 110 to be tappable over the banner) */}
                    <DashboardMenuButton onMenuClick={onMenuClick} isEasyMode={isEasyMode} t={t} />
                </div>
            )}
            {/* END Unified Banner */}


            {/* 2. MAIN ICON GRID */}
            <div style={{ 
                display: 'flex', 
                flexWrap: 'wrap', 
                justifyContent: 'center', 
                paddingTop: '15px', // Maintains standard spacing below the banner
                paddingBottom: '40px' 
            }}>
                
                {/* Icons... */}
                <Icon 
                    name={t('medical_menu.access_card_short')} 
                    emoji="🏥" 
                    isActive={true} 
                    onClick={goToMedical} 
                    isEasyMode={isEasyMode}
                    keyName={'medical_menu.access_card_short'} 
                />
                
                <Icon 
                    name={t('dashboard.emergency_info_card')} 
                    emoji="🆘" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={goToEmergencyInfo} 
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.emergency_info_card'} 
                />
                
                <Icon 
                    name={t('dashboard.medical_history_card')} 
                    emoji="📜" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={() => console.log('Medical History page route needed.')}
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.medical_history_card'} 
                />
                
                <div style={{ width: '40%', margin: '15px', visibility: 'hidden' }}></div>
            </div>

            {/* CSS Animation for the whole alert box to blink/pulse */}
            <style jsx>{`
                @keyframes blink-alert {
                    0% { 
                        box-shadow: 0 8px 15px rgba(255, 193, 7, 0.4); 
                        transform: scale(1);
                    }
                    50% { 
                        box-shadow: 0 8px 25px rgba(255, 193, 7, 0.8); 
                        transform: scale(1.005);
                    }
                    100% { 
                        box-shadow: 0 8px 15px rgba(255, 193, 7, 0.4); 
                        transform: scale(1);
                    }
                }
            `}</style>
        </div>
    );
}

export default Dashboard;
